alter table profiles add column city text not null default '', add column state text not null default '', add column language text not null default 'en', add column account_kind text not null default 'person' check(account_kind in ('person','business','journalist','news','official')), add column suspended boolean not null default false, add column reputation integer not null default 0;
grant update(city,state,language) on profiles to authenticated;
create table posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references profiles on delete cascade,body text not null check(length(body) between 1 and 500),language text not null default 'en',city text not null default '',state text not null default '',reply_to uuid references posts on delete set null,quote_of uuid references posts on delete set null,thread_parent uuid references posts on delete set null,ai_generated boolean not null default false,source_url text,limited boolean not null default false,slow_seconds integer not null default 0,like_count integer not null default 0,reply_count integer not null default 0,created_at timestamptz not null default now());
create index posts_feed on posts(author_id,created_at desc,id desc);
create index posts_local on posts(city,state,created_at desc);
create index posts_search on posts using gin(to_tsvector('simple',body));
create table blocks(owner_id uuid references profiles on delete cascade,target_id uuid references profiles on delete cascade,primary key(owner_id,target_id),check(owner_id<>target_id));
create table mutes(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles on delete cascade,account_id uuid references profiles on delete cascade,word text,topic text,check(num_nonnulls(account_id,word,topic)=1));
create table likes(user_id uuid references profiles on delete cascade,post_id uuid references posts on delete cascade,created_at timestamptz default now(),primary key(user_id,post_id));
create table reposts(user_id uuid references profiles on delete cascade,post_id uuid references posts on delete cascade,created_at timestamptz default now(),primary key(user_id,post_id));
create table bookmarks(user_id uuid references profiles on delete cascade,post_id uuid references posts on delete cascade,primary key(user_id,post_id));
create table not_helpful(user_id uuid references profiles on delete cascade,post_id uuid references posts on delete cascade,primary key(user_id,post_id));
create table post_media(id uuid primary key default gen_random_uuid(),post_id uuid not null references posts on delete cascade,path text not null,kind text not null check(kind in('image','video','voice')),bytes integer check(bytes>0 and bytes<=26214400),duration_seconds integer check(duration_seconds<=120),scan_status text not null default 'pending' check(scan_status in('pending','safe','rejected')));
create table hashtags(id bigint generated always as identity primary key,name text unique not null);
create table post_hashtags(post_id uuid references posts on delete cascade,hashtag_id bigint references hashtags on delete cascade,primary key(post_id,hashtag_id));
create table topics(id uuid primary key default gen_random_uuid(),name text unique not null,category text not null default 'general');
create table post_topics(post_id uuid references posts on delete cascade,topic_id uuid references topics on delete cascade,primary key(post_id,topic_id));
create table profile_topics(user_id uuid references profiles on delete cascade,topic_id uuid references topics on delete cascade,primary key(user_id,topic_id));
create table lists(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles on delete cascade,name text not null check(length(name)<=80));
create table list_members(list_id uuid references lists on delete cascade,profile_id uuid references profiles on delete cascade,primary key(list_id,profile_id));
create table reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references profiles on delete cascade,post_id uuid references posts on delete cascade,target_id uuid references profiles on delete cascade,reason text not null check(length(reason) between 3 and 2000),status text not null default 'open',created_at timestamptz not null default now(),check(post_id is not null or target_id is not null));
create table moderator_roles(user_id uuid primary key references profiles on delete cascade);
create table moderation_actions(id uuid primary key default gen_random_uuid(),moderator_id uuid not null references profiles,target_id uuid references profiles,post_id uuid references posts,action text not null check(action in('label','limit','suspend','restore')),reason text not null,created_at timestamptz not null default now());
create table appeals(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,action_id uuid references moderation_actions,reason text not null,status text not null default 'pending' check(status in('pending','accepted','rejected')),created_at timestamptz default now());
create table notes(id uuid primary key default gen_random_uuid(),author_id uuid not null references profiles on delete cascade,post_id uuid not null references posts on delete cascade,body text not null check(length(body) between 10 and 1000),source_url text not null,published boolean not null default false,created_at timestamptz default now());
create table note_ratings(note_id uuid references notes on delete cascade,user_id uuid references profiles on delete cascade,helpful boolean not null,primary key(note_id,user_id));
create table conversations(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles on delete cascade,name text,kind text not null default 'direct' check(kind in('direct','group','room')),created_at timestamptz default now());
create table conversation_members(conversation_id uuid references conversations on delete cascade,user_id uuid references profiles on delete cascade,accepted boolean not null default false,primary key(conversation_id,user_id));
create table messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references conversations on delete cascade,sender_id uuid not null references profiles on delete cascade,body text not null check(length(body) between 1 and 4000),created_at timestamptz not null default now());
create index messages_cursor on messages(conversation_id,created_at,id);
create table subscriptions(id uuid primary key default gen_random_uuid(),subscriber_id uuid not null references profiles on delete cascade,creator_id uuid not null references profiles on delete cascade,provider_ref text unique,status text not null default 'pending',test_mode boolean not null default true check(test_mode));
create table tips(id uuid primary key default gen_random_uuid(),payer_id uuid not null references profiles on delete cascade,creator_id uuid not null references profiles on delete cascade,amount_paise integer not null check(amount_paise>0),provider_ref text unique,status text not null default 'pending',test_mode boolean not null default true check(test_mode));
create table organizations(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles on delete cascade,name text not null,verification_status text not null default 'pending');
create table ads(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles on delete cascade,post_id uuid not null references posts on delete cascade,status text not null default 'pending',brand_safe boolean not null default false,budget_paise integer not null default 0 check(budget_paise>=0));
create table ad_events(id uuid primary key default gen_random_uuid(),ad_id uuid not null references ads on delete cascade,user_id uuid references profiles on delete set null,kind text not null check(kind in('impression','click')),created_at timestamptz default now());
create table notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,actor_id uuid references profiles on delete cascade,kind text not null,post_id uuid references posts on delete cascade,read_at timestamptz,created_at timestamptz default now());
create index notifications_cursor on notifications(user_id,created_at desc,id);
create table notification_settings(user_id uuid primary key references profiles on delete cascade,replies boolean not null default true,mentions boolean not null default true,follows boolean not null default true,reposts boolean not null default true,notes boolean not null default true,dm boolean not null default true,push_token text);
create table translations_cache(post_id uuid references posts on delete cascade,language text,body text not null,provider text not null,primary key(post_id,language));
create table polls(id uuid primary key default gen_random_uuid(),post_id uuid unique not null references posts on delete cascade,ends_at timestamptz not null);
create table poll_options(id uuid primary key default gen_random_uuid(),poll_id uuid references polls on delete cascade,label text not null);
create table poll_votes(poll_id uuid references polls on delete cascade,user_id uuid references profiles on delete cascade,option_id uuid references poll_options on delete cascade,primary key(poll_id,user_id));
create table events(id uuid primary key default gen_random_uuid(),title text not null,category text not null,region text,starts_at timestamptz);
create table event_posts(event_id uuid references events on delete cascade,post_id uuid references posts on delete cascade,primary key(event_id,post_id));
create table verification_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,kind text not null check(kind in('human','organization')),status text not null default 'pending',created_at timestamptz default now());
create table takedown_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,post_id uuid references posts on delete cascade,reason text not null,status text not null default 'pending',created_at timestamptz default now());
create table privacy_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,kind text not null check(kind in('export','delete')),status text not null default 'pending',created_at timestamptz default now());
create table consents(user_id uuid references profiles on delete cascade,purpose text,granted boolean not null,version text not null,updated_at timestamptz default now(),primary key(user_id,purpose));
create table collaborations(id uuid primary key default gen_random_uuid(),brand_id uuid not null references profiles on delete cascade,title text not null,description text not null,budget_paise integer check(budget_paise>0));
create table revenue_shares(id uuid primary key default gen_random_uuid(),creator_id uuid not null references profiles on delete cascade,ad_id uuid references ads,amount_paise integer not null check(amount_paise>=0),period date not null);
create function is_moderator() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from moderator_roles where user_id=auth.uid()) $$;
create function blocked_between(a uuid,b uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from blocks where(owner_id=a and target_id=b) or(owner_id=b and target_id=a)) $$;
create function owns_post(p uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from posts where id=p and author_id=auth.uid())$$;
create function member_of(c uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from conversation_members where conversation_id=c and user_id=auth.uid() and accepted)$$;
create function owns_conversation(c uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from conversations where id=c and owner_id=auth.uid())$$;
