create policy mutes_write on mutes for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy bookmarks_write on bookmarks for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy not_helpful_write on not_helpful for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy profile_topics_write on profile_topics for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy lists_write on lists for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy notification_settings_write on notification_settings for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy consents_write on consents for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy reports_insert on reports for insert to authenticated with check(reporter_id=auth.uid() and status in ('pending','open'));
create policy appeals_insert on appeals for insert to authenticated with check(user_id=auth.uid() and status in ('pending','open'));
create policy verification_requests_insert on verification_requests for insert to authenticated with check(user_id=auth.uid() and status in ('pending','open'));
create policy takedown_requests_insert on takedown_requests for insert to authenticated with check(user_id=auth.uid() and status in ('pending','open'));
create policy privacy_requests_insert on privacy_requests for insert to authenticated with check(user_id=auth.uid() and status in ('pending','open'));
create policy likes_write on likes for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and exists(select 1 from posts where id=post_id and not blocked_between(auth.uid(),author_id)));
create policy reposts_write on reposts for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and exists(select 1 from posts where id=post_id and not blocked_between(auth.uid(),author_id)));
drop policy posts_read on posts;
create policy posts_read on posts for select using(not limited and not blocked_between(auth.uid(),author_id) or author_id=auth.uid() or is_moderator());
create policy posts_insert on posts for insert to authenticated with check(author_id=auth.uid() and not limited and slow_seconds=0 and like_count=0 and reply_count=0);
create policy posts_delete on posts for delete to authenticated using(author_id=auth.uid());
create policy media_read on post_media for select using(scan_status='safe' or owns_post(post_id));
create policy media_insert on post_media for insert to authenticated with check(owns_post(post_id) and scan_status='pending');
create policy list_members_access on list_members for all to authenticated using(exists(select 1 from lists where id=list_id and owner_id=auth.uid())) with check(exists(select 1 from lists where id=list_id and owner_id=auth.uid()));
create policy notes_insert on notes for insert to authenticated with check(author_id=auth.uid() and not published and exists(select 1 from profiles where id=auth.uid() and reputation>=10));
create policy ratings_write on note_ratings for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and exists(select 1 from profiles where id=auth.uid() and reputation>=10));
create policy conversations_access on conversations for select to authenticated using(owner_id=auth.uid() or member_of(id));
create policy conversations_create on conversations for insert to authenticated with check(owner_id=auth.uid());
create policy members_read on conversation_members for select to authenticated using(user_id=auth.uid() or member_of(conversation_id) or owns_conversation(conversation_id));
create policy members_invite on conversation_members for insert to authenticated with check(owns_conversation(conversation_id) and not blocked_between(auth.uid(),user_id) and (not accepted or user_id=auth.uid()));
create policy members_accept on conversation_members for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
revoke update on conversation_members from authenticated;grant update(accepted) on conversation_members to authenticated;
create policy messages_read on messages for select to authenticated using(member_of(conversation_id) and not blocked_between(auth.uid(),sender_id));
create policy messages_send on messages for insert to authenticated with check(sender_id=auth.uid() and member_of(conversation_id) and not exists(select 1 from conversation_members m where m.conversation_id=messages.conversation_id and blocked_between(auth.uid(),m.user_id)));
create policy translations_read on translations_cache for select using(exists(select 1 from posts where id=post_id));
create policy moderation_read on moderation_actions for select to authenticated using(is_moderator() or target_id=auth.uid());
create policy moderation_insert on moderation_actions for insert to authenticated with check(is_moderator() and moderator_id=auth.uid());
create policy report_queue on reports for select to authenticated using(is_moderator());
create policy appeals_queue on appeals for select to authenticated using(is_moderator());
create policy moderator_self on moderator_roles for select to authenticated using(user_id=auth.uid());
create policy ads_public on ads for select using(status='approved' and brand_safe);
create policy ad_events_insert on ad_events for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from ads where id=ad_id and status='approved' and brand_safe));
create function enforce_post_limits() returns trigger language plpgsql security definer set search_path=public as $$
declare age interval; count_recent integer; parent posts;begin
 perform pg_advisory_xact_lock(hashtextextended(new.author_id::text,0));
 select now()-created_at into age from profiles where id=new.author_id and not suspended;
 if age is null then raise exception 'Account cannot post';end if;
 select count(*) into count_recent from posts where author_id=new.author_id and created_at>now()-interval '1 hour';
 if count_recent >= (case when age<interval '7 days' then coalesce((select value from platform_settings where key='new_posts_per_hour'),5)else coalesce((select value from platform_settings where key='posts_per_hour'),30)end) then raise exception 'Posting rate limit reached';end if;
 if exists(select 1 from posts where author_id=new.author_id and body=new.body and created_at>now()-interval '1 day') then raise exception 'Duplicate post';end if;
 if new.reply_to is not null then select * into parent from posts where id=new.reply_to;
 if blocked_between(new.author_id,parent.author_id) then raise exception 'Reply unavailable';end if;
 if parent.slow_seconds>0 and exists(select 1 from posts where author_id=new.author_id and reply_to=new.reply_to and created_at>now()-make_interval(secs=>parent.slow_seconds)) then raise exception 'Slow mode: wait before replying';end if;end if;return new;end $$;
create trigger post_limits before insert on posts for each row execute function enforce_post_limits();
create function follow_limits() returns trigger language plpgsql security definer set search_path=public as $$begin
 perform pg_advisory_xact_lock(hashtextextended(new.follower_id::text,1));
 if blocked_between(new.follower_id,new.followee_id) or exists(select 1 from profiles where id=new.follower_id and suspended) then raise exception 'Follow unavailable';end if;
 if(select count(*) from follows where follower_id=new.follower_id and created_at>now()-interval '1 hour')>=20 then raise exception 'Follow rate limit reached';end if;return new;end $$;
create trigger follow_limit before insert on follows for each row execute function follow_limits();
create function update_like_count() returns trigger language plpgsql security definer set search_path=public as $$begin
 if TG_OP='INSERT' then update posts set like_count=like_count+1 where id=new.post_id;return new;else update posts set like_count=greatest(0,like_count-1) where id=old.post_id;return old;end if;end $$;
create trigger like_counter after insert or delete on likes for each row execute function update_like_count();
create function moderation_apply() returns trigger language plpgsql security definer set search_path=public as $$begin
 if new.action='suspend' then update profiles set suspended=true where id=new.target_id;
 elsif new.action='restore' then update profiles set suspended=false where id=new.target_id;update posts set limited=false where id=new.post_id;
 elsif new.action='limit' then update posts set limited=true where id=new.post_id;end if;return new;end $$;
create trigger apply_moderation after insert on moderation_actions for each row execute function moderation_apply();
alter publication supabase_realtime add table posts,messages,notifications;
